.caja {
  transform: translateX(0);
  transition: transform 300ms ease;   /* qué propiedad, cuánto dura, con qué curva */
}
.caja.on {
  transform: translateX(200px);       /* basta con cambiar el estado: el navegador anima la diferencia */
}

// Medir cuadros caídos con requestAnimationFrame (corre en el navegador; acá va el esqueleto).
const FRAME_MS = 1000 / 60;             // 16,67 ms por cuadro a 60 Hz
function medirCuadros(deltas) {         // deltas: tiempo entre cuadros consecutivos, en ms
  let caidos = 0, peor = 0;
  for (const d of deltas) {
    peor = Math.max(peor, d);
    caidos += Math.max(0, Math.round(d / FRAME_MS) - 1);   // un salto de 100 ms equivale a ~5 cuadros que no se dibujaron
  }
  return { cuadros: deltas.length, caidos, peor: +peor.toFixed(1) };
}
// Ejemplo con datos armados a mano: 30 cuadros parejos y uno de 117 ms
const deltas = [...Array(30).fill(16.7), 117, ...Array(30).fill(16.7)];
console.log(medirCuadros(deltas));
console.log("A 120 Hz un cuadro dura", (1000 / 120).toFixed(2), "ms; a 30 Hz,", (1000 / 30).toFixed(2), "ms");

const anim = caja.animate(
  [{ transform: "translateX(0)", opacity: 1 },
   { transform: "translateX(200px)", opacity: 0.4 }],
  { duration: 400, easing: "ease-out", fill: "forwards" }
);
anim.pause();                 // detener a mitad de camino
anim.play();                  // seguir
await anim.finished;          // una promesa que se resuelve cuando termina
anim.playbackRate = -1;       // la misma animación, hacia atrás
anim.play();

// Una curva cubic-bezier(x1, y1, x2, y2) de CSS: la forma va de (0,0) a (1,1) con dos puntos de control.
// Dado el tiempo transcurrido t (0 a 1), hay que encontrar el parámetro s de la curva donde x(s) = t y devolver y(s).
function cubicBezier(x1, y1, x2, y2) {
  const punto = (a, b, s) => 3 * (1 - s) * (1 - s) * s * a + 3 * (1 - s) * s * s * b + s * s * s;
  return (t) => {
    let lo = 0, hi = 1;
    for (let i = 0; i < 40; i++) {            // búsqueda binaria: x(s) crece con s
      const s = (lo + hi) / 2;
      if (punto(x1, x2, s) < t) lo = s; else hi = s;
    }
    return punto(y1, y2, (lo + hi) / 2);
  };
}
const curvas = {
  "linear":      (t) => t,
  "ease":        cubicBezier(0.25, 0.1, 0.25, 1),
  "ease-in":     cubicBezier(0.42, 0, 1, 1),
  "ease-out":    cubicBezier(0, 0, 0.58, 1),
  "ease-in-out": cubicBezier(0.42, 0, 0.58, 1),
};
console.log("curva".padEnd(12), "t=0.25", "t=0.50", "t=0.75");
for (const [nombre, f] of Object.entries(curvas)) {
  console.log(nombre.padEnd(12), [0.25, 0.5, 0.75].map((t) => f(t).toFixed(3).padStart(6)).join(" "));
}
// Con 300 ms y un recorrido de 200 px: dónde está la caja a los 75 ms (t = 0.25)
console.log("A los 75 ms, con ease-out:", (200 * curvas["ease-out"](0.25)).toFixed(1), "px de 200");
console.log("A los 75 ms, con ease-in: ", (200 * curvas["ease-in"](0.25)).toFixed(1), "px de 200");

.panel {
  transition: transform 250ms ease-out, opacity 250ms ease-out;
}
@media (prefers-reduced-motion: reduce) {
  .panel {
    transition: opacity 150ms linear;  /* sin desplazamiento: solo aparece */
  }
}

const mq = matchMedia("(prefers-reduced-motion: reduce)");
let quieto = mq.matches;                       // true si la persona pidió menos movimiento
mq.addEventListener("change", (e) => { quieto = e.matches; });   // cambia en vivo si lo activa en el sistema

bloques.solucion:
.panel { transform: translateX(100%); opacity: 0; transition: transform 250ms ease-out, opacity 250ms ease-out; }
.panel.abierto { transform: translateX(0); opacity: 1; }
@media (prefers-reduced-motion: reduce) {
  .panel { transform: translateX(0); transition: opacity 150ms linear; }
}
En la versión reducida el panel siempre está en su lugar y solo cambia la opacidad. Si lo dejaras con translateX(100%), seguiría apareciendo desde el costado aunque no se animara.
